def make_state(key):
    import re
    from app.services.document_workflow import normalize_field
    scenario=SCENARIOS[key];values={**VALUES,**OVERRIDES.get(key,{})}
    if key=='contract_employment':
        values.update(authority_basis='Устав организации',recipient_details='Паспорт: серия 6500, номер 123456, выдан 01.02.2018 ОМВД России по тестовому району.',payment='15 и 30 числа каждого месяца, банковским переводом',leave_context='Общеобразовательная школа, общеобразовательные классы.',position='учитель математики',workplace='Школа № 10, г. Екатеринбург, ул. Примерная, д. 10',
            job_function='Работник преподаёт математику в 5–9 классах.',employment_type='основная работа',
            term_type='на неопределённый срок',fixed_term=None,pay_conditions='Оклад установлен за месяц работы. Дополнительные надбавки не согласованы.',
            schedule='Рабочая неделя составляет 36 часов, выходные дни — суббота и воскресенье.',
            work_conditions='Условия труда на рабочем месте относятся к классу 2.',compensations=None,is_pedagogue='да',
            teaching_load='18 часов преподавания в неделю по математике',education_details='Для должности требуется высшее педагогическое образование.',
            vacation='56 календарных дней',probation=None)
    state=new_state(scenario.title);state.update(scenario=key,phase='ready',text_package=load_text_package(scenario))
    for field in scenario.fields:
        if field.key in {'legal_basis','fee','jurisdiction','claim_price'}:
            state['fields'][field.key]={'status':'review_required','value':None};continue
        if field.kind=='choice':
            choices={'deposit':'да','interest_type':'беспроцентный','restoration':'не восстановлено','expertise':'нет','security':'нет','copy_status':'направлены'}
            value=values.get(field.key,choices.get(field.key,field.choices[0]))
        else:
            if field.key not in values:raise ValueError(key+': missing acceptance source '+field.key)
            value=values[field.key]
        if value is not None and field.kind in {'date','money','address','duration','choice'}:
            normalized,error=normalize_field(field,value)
            if error and field.kind=='date':
                matches=re.findall(r'\d{1,2}[./]\d{1,2}[./]\d{4}',value)
                if len(matches)==1:normalized,error=normalize_field(field,matches[0])
            if error:raise ValueError(key+': invalid typed fixture '+field.key+': '+error)
            value=normalized
        state['fields'][field.key]={'status':'filled' if value is not None else 'not_applicable','value':value,'original':value,'evidence':value}
    for field in scenario.fields:
        if not field_is_active(field,state['fields']):state['fields'][field.key]={'status':'not_applicable','value':None}
    prepare_form_rules(state)
    return state
